import type { MetadataRoute } from 'next';

// Web app manifest, served at /manifest.webmanifest. Icons are generated by apple-icon.tsx.
//
// orientation "any": the brief is landscape-first, but portrait must keep working (an iPad on a
// wheelchair mount or a stand may be portrait). Locking would force a rotation the user may not
// be able to make. iPadOS does not enforce manifest orientation anyway; layout handles both.
//
// Colors: the manifest takes one value, so it uses the default (light) --bg from globals.css.
// The per-scheme theme-color <meta> tags from layout.tsx's `viewport` export take precedence in
// browsers that support media-dependent theme colors.
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: '/',
    name: 'Still Here',
    short_name: 'Still Here',
    description: 'Context-aware AAC: your words, your choice.',
    start_url: '/',
    scope: '/',
    display: 'standalone',
    orientation: 'any',
    background_color: '#f5f4f0',
    theme_color: '#f5f4f0',
    lang: 'en',
    categories: ['accessibility', 'health', 'utilities'],
    icons: [
      { src: '/apple-icon/192', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '/apple-icon/512', sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: '/apple-icon/maskable', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
  };
}
